import {dailyPlanner} from './lastplanner-daily-ui.mjs';
export function resourceAssistant(form,initial={},context={}){
 form.dataset.resourceAssistant='true';
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),work=form.querySelector('[data-step="0"]'),plan=form.querySelector('[data-step="2"] details');
 const block=document.createElement('div');block.hidden=true;block.innerHTML=`<input type="hidden" data-part-name value="${esc(initial.partida?.name||'')}"><input type="hidden" data-family value="${esc(initial.partida?.family||'')}">`;work.append(block);
 const box=document.createElement('div');box.innerHTML=`<label>Base del rendimiento<select data-rate-basis>${['persona-dia','persona-hora','cuadrilla-dia','cuadrilla-hora'].map(v=>`<option value="${v}" ${v===initial.basis?'selected':''}>${v.replace('-dia',' por día').replace('-hora',' por hora')}</option>`).join('')}</select></label><label>Unidad del rendimiento<input data-rate-unit value="${esc(initial.unit||form.elements.unidad.value)}"></label><label>Horas efectivas por día (solo rendimientos horarios)<input type="number" min="0" max="24" step="any" data-hours value="${esc(initial.hours||'')}"></label><label>Cuadrillas previstas<input data-planned-crews type="number" min="0" step="1" value="${esc(initial.plannedCrews??'')}"></label><label>Composición de una cuadrilla: rol y cantidad, una línea por rol<textarea data-crew placeholder="Rol: cantidad">${esc((initial.crew||[]).map(r=>r.role+': '+r.count).join('\n'))}</textarea></label><label>Notas del rendimiento (opcional)<textarea data-rate-notes>${esc(initial.notes??(initial.version===1&&initial.source&&!/^\d+$/.test(initial.source)?initial.source:''))}</textarea><input type="hidden" data-rate-source value="Estimación provisional del supervisor"></label><p data-recommendation role="status"></p>`;plan.append(box);
 let daily=null;
 const read=()=>({...initial,...daily?.read(),previousReference:initial.previousReference||(initial.version===1?structuredClone(initial):null),apu:context.apu?context.apu():initial.apu||null,version:2,people:form.elements.dotacion.value===''?null:Number(form.elements.dotacion.value),plannedCrews:box.querySelector('[data-planned-crews]').value===''?null:Number(box.querySelector('[data-planned-crews]').value),partida:{name:(context.apu?.()?.operation?.label||context.apu?.()?.description)||block.querySelector('[data-part-name]').value.trim()||form.elements.actividad.value.trim(),family:block.querySelector('[data-family]').value},basis:box.querySelector('[data-rate-basis]').value,unit:box.querySelector('[data-rate-unit]').value.trim(),rate:Number(form.elements.rendimientoPlan.value)||null,hours:Number(box.querySelector('[data-hours]').value)||null,crew:box.querySelector('[data-crew]').value.split('\n').filter(v=>v.trim()).map(v=>{const i=v.lastIndexOf(':');return {role:i<0?'':v.slice(0,i).trim(),count:i<0?0:Number(v.slice(i+1))};}),source:daily?.read().estimateReference.source||box.querySelector('[data-rate-source]').value.trim(),notes:box.querySelector('[data-rate-notes]').value.trim(),status:daily?.read().estimateReference.status||'provisional',calendar:'jornadas-programadas-explicitamente'});
 function update(){
  if(!Number(form.elements.rendimientoPlan.value))box.querySelector('[data-rate-unit]').value=form.elements.unidad.value;
  const v=read(),byCrew=v.basis.startsWith('cuadrilla');
  box.querySelector('[data-hours]').closest('label').hidden=true;box.querySelector('[data-crew]').closest('label').hidden=!byCrew;box.querySelector('[data-planned-crews]').closest('label').hidden=true;
  form.elements.rendimientoPlan.closest('label').firstChild.textContent='Rendimiento ('+v.unit+'/'+v.basis.replace('-dia','-jornada')+')';
  box.querySelector('[data-recommendation]').hidden=true;
  form.querySelector('[data-wizard-capacity]').hidden=true;

 }
 form.addEventListener('input',e=>{if(e.target.name==='rendimientoPlan')box.querySelector('[data-rate-unit]').value=form.elements.unidad.value;update();});form.addEventListener('change',update);form.addEventListener('click',()=>queueMicrotask(update));daily=dailyPlanner(form,initial,context);update();return {read,pending:()=>daily.pending()};
}
